      boosterSpeedAlpha: hudInfoClampNumber(source.boosterSpeedAlpha, 0, 1, DEFAULT_HUD_INFO_RUNTIME_SETTINGS.boosterSpeedAlpha),
      boosterVirusColor: hudInfoNormalizeColor(source.boosterVirusColor, DEFAULT_HUD_INFO_RUNTIME_SETTINGS.boosterVirusColor),
      boosterVirusAlpha: hudInfoClampNumber(source.boosterVirusAlpha, 0, 1, DEFAULT_HUD_INFO_RUNTIME_SETTINGS.boosterVirusAlpha),
      positionMode: HUD_INFO_POSITION_MODES_SET.has(source.positionMode) ? source.positionMode : DEFAULT_HUD_INFO_RUNTIME_SETTINGS.positionMode,
      layoutMode: HUD_INFO_LAYOUT_MODES_SET.has(source.layoutMode) ? source.layoutMode : DEFAULT_HUD_INFO_RUNTIME_SETTINGS.layoutMode,
      fontSize: hudInfoClampNumber(source.fontSize, 10, 32, DEFAULT_HUD_INFO_RUNTIME_SETTINGS.fontSize),
