    const normalizedMaskId = Object.hasOwn(VIRUS_MOTHER_CELL_ASSET_URLS, maskId) ? maskId : 'halo';
    return VIRUS_MOTHER_CELL_ASSET_URLS[normalizedMaskId] || '';
